#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
struct Edge{int u,v; long long w;};
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr); int n,m; if(!(cin>>n>>m)) return 0; vector<Edge> e(m); for(auto &x:e) cin>>x.u>>x.v>>x.w; sort(e.begin(),e.end(),[](const Edge&a,const Edge&b){return a.w<b.w;}); if(n==1){ cout<<0<<'\n'; return 0; } if(m<n-1){ cout<<"orz\n"; return 0; } long long total=0; for(int i=0;i<n-1;i++) total+=e[i].w; cout<<total<<'\n'; return 0; }
